"use strict";(globalThis.webpackChunkgrc||=[]).push([[44984],{56079(e){e.exports=JSON.parse('{"citeKey":"sun1995performanceconsiderations","slug":"sun-1995-performance-considerations-60ca","title":"Performance Considerations of Shared Virtual Memory Machines","authors":["X.-H. Sun","J. Zhu"],"venue":"IEEE Trans. on Parallel and Distributed Systems","type":"Journal","entryType":"article","date":"November, 1995","year":1995,"era":"archive","month":11,"doi":"10.1109/71.476190","abstract":"Generalized speedup is defined as parallel speed over sequential speed. In this paper the generalized speedup and its relation with other existing performance metrics, such as tra- ditional speedup, efficiency, scalability, etc., are carefully studied. In terms of the introduced asymptotic speed, we show that the difference between the generalized speedup and the traditional speedup lies in the definition of the efficiency of uniprocessor processing, which is a very important issue in shared virtual memory machines. A scientific application has been implemented on a KSR-1 parallel computer. Experimental and theoretical re- sults show that the generalized speedup is distinct from the tradi- tional speedup and provides a more reasonable measurement. In the study of different speedups, an interesting relation between fixed-time and memory-bounded speedup is revealed. Various causes of superlinear speedup are also presented.","hasAbstract":true,"lede":"The generalized speedup and its relation with other existing performance metrics, such as tra- ditional speedup, efficiency, scalability, etc., are carefully studied.","links":{"pdf":"https://grc.iit.edu/papers/1995/sun-1995-performance-considerations-60ca.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);